# Мнемоники кандзи: составные части из KRADFILE (EDRDG, CC BY-SA 4.0) + русские названия ключей + истории для N5.
# python -X utf8 tools/build_mnemonics.py <проект> <kradfile.gz>
import gzip, json, os, sys
proj, krad = sys.argv[1], sys.argv[2]
D = lambda f: os.path.join(proj, "Data", f)
parts = {}
for line in gzip.open(krad).read().decode("euc_jp", errors="replace").split("\n"):
    if line and not line.startswith("#") and " : " in line:
        k, comps = line.split(" : ", 1)
        parts[k.strip()] = comps.split()

