kanji = [k[0] for f in ("kanji.json", "kanji_n4.json", "kanji_n3.json") for k in json.load(open(D(f), encoding="utf8"))]
out = {}
for k in kanji:
    comps = [c for c in parts.get(k, []) if c != k][:5]
    DISPLAY = {"化": "亻", "个": "𠆢", "并": "丷", "刈": "刂", "込": "辶", "尚": "⺌", "忙": "忄", "扎": "扌", "汁": "氵", "犯": "犭",
               "艾": "艹", "邦": "阝", "阡": "阝", "老": "耂", "杰": "灬", "礼": "礻", "疔": "疒", "禹": "禸", "初": "衤", "買": "罒", "滴": "啇"}
    NAMES = {"化": "человек", "汁": "вода", "忙": "сердце", "扎": "рука", "犯": "зверь", "艾": "трава", "邦": "деревня", "阡": "холм", "杰": "огонь", "礼": "алтарь", "疔": "болезнь", "初": "одежда", "買": "сеть", "込": "дорога", "刈": "меч", "老": "старик"}
    named = [(DISPLAY.get(c, c), NAMES.get(c) or R.get(c, "")) for c in comps]
    out[k] = {"parts": [[c, n] for c, n in named], "story": STORY.get(k, "")}
json.dump(out, open(D("mnemonics.json"), "w", encoding="utf8"), ensure_ascii=False, separators=(",", ":"))
named_cnt = sum(1 for v in out.values() for p in v["parts"] if p[1])
print("kanji:", len(out), "with stories:", sum(1 for v in out.values() if v["story"]), "named parts:", named_cnt, "/", sum(len(v["parts"]) for v in out.values()))
print("休:", out.get("休"), "| 語:", out.get("語"))
